<?php namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; class AuthController{function show(){return view('auth.login');} function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required']); if(Auth::attempt($data)){ $r->session()->regenerate(); return redirect()->intended('/');} return back()->withErrors(['email'=>'Login fehlgeschlagen.']);} function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}}
